def choose(usage, engines, coverage_pct):
    ordered = sorted(usage, key=lambda b: -usage[b])
    chosen, total = [], 0
    for b in ordered:
        if total >= coverage_pct:
            break
        chosen.append(b)
        total += usage[b]
    covered = {engines[b] for b in chosen}
    for b in ordered:
        if engines[b] not in covered:
            chosen.append(b)
            covered.add(engines[b])
    return chosen

